const status=document.getElementById('standalone-status'),statusText=document.getElementById('standalone-status-text');
const monitorWait=(ms)=>new Promise(r=>setTimeout(r,ms));
const monitor=async()=>{const t0=performance.now();while(!window.__GAME__&&!window.__SHOT_FAILED__&&performance.now()-t0<180000)await monitorWait(100);if(window.__SHOT_FAILED__){statusText.textContent='Game startup failed: '+window.__SHOT_FAILED__;return}if(!window.__GAME__){statusText.textContent='Game startup timed out. Reload to try again.';return}const t1=performance.now();while(window.__GAME__.runner.status().some(s=>['loaded','created'].includes(s.status))&&performance.now()-t1<180000)await monitorWait(100);await window.__GAME__.ctx.assets.whenIdle();const t2=performance.now();let warned=false;while(!window.__APP_STARTUP_READY__&&!window.__SHOT_FAILED__){if(!warned&&performance.now()-t2>240000){warned=true;statusText.textContent='Map rendering is taking longer than expected. Still working…'}await monitorWait(150)}if(window.__SHOT_FAILED__){statusText.textContent='Game startup failed: '+window.__SHOT_FAILED__;return}status.classList.add('hidden')};
